package com.thang.nihongo_user.service;
import com.thang.nihongo_user.model.*;import com.thang.nihongo_user.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.*;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor
public class LearningFeaturesService {
 private final LessonCompletionRepository completions;private final ClassroomContentClient content;private final StudyActivityService activity;private final StudyCardRepository cards;private final IUserExerciseAttemptRepository attempts;private final IUserSubscriptionRepository subscriptions;private final ICourseRepository courses;
 public record Recommendation(String key,String title,String explanation,String path){}
 @Transactional(readOnly=true) public boolean completed(String userId,Long lessonId){return completions.findByUserIdAndLessonId(userId,lessonId).isPresent();}
 // The lesson/entitlement lookup is remote; only the final writes run inside a DB transaction.
 private org.springframework.transaction.support.TransactionOperations transactions=org.springframework.transaction.support.TransactionOperations.withoutTransaction();
 @org.springframework.beans.factory.annotation.Autowired(required=false) void setTransactionManager(org.springframework.transaction.PlatformTransactionManager manager){transactions=new org.springframework.transaction.support.TransactionTemplate(manager);}
 public void complete(String userId,Long lessonId,boolean completed){if(!completed){transactions.executeWithoutResult(status->completions.remove(userId,lessonId));return;}var lesson=content.lesson(lessonId);if(lesson==null||lesson.lessonId()==null||!lessonId.equals(lesson.lessonId()))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Bài học không tồn tại hoặc không có quyền học");String name=lesson.name()==null?"Bài "+lessonId:lesson.name();transactions.executeWithoutResult(status->{completions.mark(userId,lessonId,name.substring(0,Math.min(255,name.length())),LocalDateTime.now());activity.record(userId,"lesson:"+lessonId,LocalDate.now());});}
 @Transactional(readOnly=true) public Map<String,Object> completions(String userId,int page){if(page<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Trang không hợp lệ");var result=completions.findByUserIdOrderByCompletedAtDescIdDesc(userId,PageRequest.of(page,20));return Map.of("content",result.getContent(),"number",result.getNumber(),"totalElements",result.getTotalElements(),"totalPages",result.getTotalPages());}
 @Transactional(readOnly=true) public List<Recommendation> recommendations(String userId){List<Recommendation> result=new ArrayList<>();long due=cards.countByUserIdAndDueAtLessThanEqual(userId,LocalDateTime.now());if(due>0)result.add(new Recommendation("due","Ôn "+due+" thẻ đến hạn","Củng cố các thẻ theo lịch ghi nhớ trước khi học thêm.","/user/review"));long weak=attempts.countWeakLessons(userId);if(weak>0)result.add(new Recommendation("weak","Xem lại "+weak+" bài còn yếu","Ưu tiên bài có kết quả gần nhất dưới 80 điểm, rồi luyện câu sai.","/user/review"));var active=subscriptions.findByUserIdAndStatusAndExpiredAtGreaterThanOrderByLastStudiedAtDesc(userId,SubscriptionStatus.ACTIVE,LocalDateTime.now(),PageRequest.of(0,3)).getContent();Map<Long,Course> byId=new HashMap<>();courses.findAllById(active.stream().map(UserSubscription::getCourseId).toList()).forEach(c->byId.put(c.getCourseId(),c));for(var s:active){var course=byId.get(s.getCourseId());if(course!=null&&course.getActive()==CourseStatus.ACTIVE)result.add(new Recommendation("course:"+s.getCourseId(),"Tiếp tục "+course.getCourseName(),s.getLastLessonId()==null?"Bắt đầu một bài học và đánh dấu hoàn thành khi học xong.":"Tiếp nối vị trí học gần nhất của bạn.","/course/"+s.getCourseId()));}if(result.isEmpty())result.add(new Recommendation("courses","Chọn khóa học phù hợp","Xem các khóa đang mở và chọn cấp độ muốn học.","/courses"));return result;}
}
